function topo = gs3dx_read_grip_topology(json_path)
%GS3DX_READ_GRIP_TOPOLOGY Load and validate the shared GS3DX grip topology JSON.
%
%   topo = GS3DX_READ_GRIP_TOPOLOGY() reads the repository-default file
%   appearance/gs3dx_grip_topology.json generated by
%   scripts/export_simscape_grip_topology.py (HRG-GS-M11, #13333).
%
%   topo = GS3DX_READ_GRIP_TOPOLOGY(json_path) reads a specific JSON path.
%
%   This function is a thin consumer of the Python-generated grip topology and
%   posed finger geometry. It does not re-implement ContactTopology or any
%   contact force law in MATLAB.

    if nargin < 1 || isempty(json_path)
        here = fileparts(mfilename('fullpath'));
        json_path = fullfile(fileparts(here), 'appearance', 'gs3dx_grip_topology.json');
    end

    if exist(json_path, 'file') ~= 2
        error('gs3dx:grip_topology:MissingFile', ...
            'Grip topology JSON not found at %s. Run scripts/export_simscape_grip_topology.py.', ...
            json_path);
    end

    raw = fileread(json_path);
    topo = jsondecode(raw);

    if ~isfield(topo, 'schema_version') || ~strcmp(topo.schema_version, 'simscape-grip-topology/v1')
        error('gs3dx:grip_topology:SchemaVersion', ...
            'Unsupported grip topology schema_version in %s (expected simscape-grip-topology/v1).', ...
            json_path);
    end

    required = {'model_id', 'handedness', 'attachment_mode', 'hand_frames', 'styles', 'presets'};
    for k = 1:numel(required)
        if ~isfield(topo, required{k})
            error('gs3dx:grip_topology:MissingSection', ...
                'Grip topology JSON %s is missing required section "%s".', ...
                json_path, required{k});
        end
    end
end
